#ifndef SYSTEM_HPP
#define SYSTEM_HPP

#include <iostream>
#include <vector>
#include <string>
#include <fstream>
#include <cmath>
#include <algorithm>
#include <cctype>
#include <sstream>
#include "users.hpp"

using namespace std;

enum Person
{
    NONE,
    STUDENT,
    PROFESSOR,
    MANAGER,
};

struct EnteredPerson {
    Person user;
    string id;
    string name;
    string major;
    string profile_path;
};

class System
{
public:
    System(string majors_file, string students_file, string lessons_file, string professors_file);
    void login(string id, string password);
    void posting(string title, string message, string photo_path);
    void course_offering(vector<string> order_words);
    void check_course_id(int coures_id);
    void check_professor_id(int coures_id, string professor_id);
    void check_course_time(string professor_id, string course_time);
    void add_offered_lesson(string professor_id, string time, string exam_date, int course_id, int capacity, int class_number);
    void view_lessons(vector<string> order_words);
    void register_for_lesson(vector<string> order_words);
    void delete_course(vector<string> order_words);
    void view_own_courses(vector<string> order_words);
    void setting_profile(vector<string> order_words);
    void view_channel(vector<string> order_words);
    User* find_user_by_id(string id);
    string who_are_you(string id);
    EnteredPerson entered_person;

private:
    vector<Lesson *> lessons;
    vector<User *> users;
    vector<Course *> offered_courses;
};

#endif
